static indigo_property_state sequence_state(void) {
	pthread_mutex_lock(&cache_mutex);
	observation *entry = find(SCRIPTING_AGENT_NAME, "SEQUENCE_STATE");
	indigo_property_state state = entry && entry->property ? entry->property->state : (indigo_property_state)-1;
	pthread_mutex_unlock(&cache_mutex);
	return state;
}

static bool wait_sequence_state(indigo_property_state state, double timeout) {
	for (double t = 0; t < timeout; t += 0.01) {
		if (sequence_state() == state) {
			return true;
		}
		indigo_usleep(10000);
	}
	fprintf(stderr, "Timeout waiting for SEQUENCE_STATE %d, observed %d\n", state, sequence_state());
	return false;
}

