// label of the index-th history entry of a task given as "Name" or "Name #run", empty if none
static bool history_label(const char *task, int index, char *label) {
	char needle[INDIGO_VALUE_SIZE];
	const char *run = strstr(task, " #");
	if (run) {
		snprintf(needle, sizeof(needle), " | %.*s | run %s | ", (int)(run - task), task, run + 2);
	} else {
		snprintf(needle, sizeof(needle), " | %s | ", task);
	}
	indigo_property *property = snapshot(AGENT_SCHEDULER_HISTORY_PROPERTY_NAME);
	bool found = false;
	int seen = 0;
	if (property) {
		for (int i = 0; i < property->count; i++) {
			if (strstr(property->items[i].label, needle) && seen++ == index) {
				strcpy(label, property->items[i].label);
				found = true;
				break;
			}
		}
		indigo_release_property(property);
	}
	return found;
}

static int history_count(void) {
	indigo_property *property = snapshot(AGENT_SCHEDULER_HISTORY_PROPERTY_NAME);
	int count = property ? property->count : -1;
	indigo_release_property(property);
	return count;
}

static void utc(time_t t, char *buffer) {
	struct tm tm_time;
	gmtime_r(&t, &tm_time);
	strftime(buffer, 32, "%Y-%m-%d %H:%M", &tm_time);
}

// -------------------------------------------------------------------------------- Stand-in agents

static indigo_result mount_enumerate(indigo_device *device, indigo_client *client, indigo_property *property) {
	if (indigo_property_match(site_property, property)) {
		indigo_define_property(device, site_property, NULL);
	}
	return INDIGO_OK;
}

static indigo_result guider_enumerate(indigo_device *device, indigo_client *client, indigo_property *property) {
	if (indigo_property_match(guider_process_property, property)) {
		indigo_define_property(device, guider_process_property, NULL);
	}
	if (indigo_property_match(guider_abort_property, property)) {
		indigo_define_property(device, guider_abort_property, NULL);
	}
	return INDIGO_OK;
}

static indigo_result guider_change(indigo_device *device, indigo_client *client, indigo_property *property) {
	if (indigo_property_match_changeable(guider_abort_property, property)) {
		atomic_fetch_add(&guider_aborts, 1);
		indigo_update_property(device, guider_abort_property, NULL);
		if (!atomic_load(&guider_stubborn)) {
			guider_process_property->state = INDIGO_ALERT_STATE;
			guider_process_property->items[0].sw.value = false;
			indigo_update_property(device, guider_process_property, "Guiding aborted");
		}
	}
	return INDIGO_OK;
}

static indigo_device mount_standin = INDIGO_DEVICE_INITIALIZER("Mount Agent", NULL, mount_enumerate, NULL, NULL, NULL);
static indigo_device guider_standin = INDIGO_DEVICE_INITIALIZER("Guider Agent", NULL, guider_enumerate, guider_change, NULL, NULL);

static bool imager_camera_selected(void) {
	return !indigo_get_item(imager_ccd_list_property, FILTER_DEVICE_LIST_NONE_ITEM_NAME)->sw.value;
}

static indigo_result imager_enumerate(indigo_device *device, indigo_client *client, indigo_property *property) {
	if (indigo_property_match(imager_ccd_list_property, property)) {
		indigo_define_property(device, imager_ccd_list_property, NULL);
	}
	if (!imager_camera_selected()) {
		return INDIGO_OK;
	}
	if (indigo_property_match(imager_local_mode_property, property)) {
		indigo_define_property(device, imager_local_mode_property, NULL);
	}
	if (indigo_property_match(imager_set_fits_property, property)) {
		indigo_define_property(device, imager_set_fits_property, NULL);
	}
	if (indigo_property_match(imager_remove_fits_property, property)) {
		indigo_define_property(device, imager_remove_fits_property, NULL);
	}
	return INDIGO_OK;
}

static void imager_record(const char *event) {
	pthread_mutex_lock(&imager_mutex);
	if (strlen(imager_log) + strlen(event) + 2 < sizeof(imager_log)) {
		strcat(imager_log, "\n");
		strcat(imager_log, event);
	}
	pthread_mutex_unlock(&imager_mutex);
}

// logs the change as LOCAL NAME=value ..., SET KEYWORD=VALUE or REMOVE KEYWORD and acknowledges it like the Imager Agent
static indigo_result imager_change(indigo_device *device, indigo_client *client, indigo_property *property) {
	indigo_property *target = NULL;
	char event[1024] = "";
	if (indigo_property_match_changeable(imager_ccd_list_property, property)) {
		indigo_property_copy_values(imager_ccd_list_property, property, false);
		bool selected = imager_camera_selected();
		snprintf(event, sizeof(event), "CAMERA %s", selected ? "SELECTED" : "NONE");
		imager_record(event);
		imager_ccd_list_property->state = INDIGO_BUSY_STATE;
		indigo_update_property(device, imager_ccd_list_property, NULL);
		indigo_property *camera_properties[] = { imager_local_mode_property, imager_set_fits_property, imager_remove_fits_property };
		for (int i = 0; i < 3; i++) {
			if (selected && !camera_properties[i]->defined) {
				indigo_define_property(device, camera_properties[i], NULL);
			} else if (!selected && camera_properties[i]->defined) {
				indigo_delete_property(device, camera_properties[i], NULL);
			}
		}
		imager_ccd_list_property->state = INDIGO_OK_STATE;
		indigo_update_property(device, imager_ccd_list_property, NULL);
		return INDIGO_OK;
	}
	if (indigo_property_match_changeable(imager_local_mode_property, property)) {
		target = imager_local_mode_property;
		strcpy(event, "LOCAL");
		for (int i = 0; i < property->count; i++) {
			snprintf(event + strlen(event), sizeof(event) - strlen(event), " %s=%s", property->items[i].name, property->items[i].text.value);
		}
	} else if (indigo_property_match_changeable(imager_set_fits_property, property)) {
		target = imager_set_fits_property;
		snprintf(event, sizeof(event), "SET %s=%s", indigo_get_text_item_value(indigo_get_item(property, CCD_SET_FITS_HEADER_KEYWORD_ITEM_NAME)), indigo_get_text_item_value(indigo_get_item(property, CCD_SET_FITS_HEADER_VALUE_ITEM_NAME)));
	} else if (indigo_property_match_changeable(imager_remove_fits_property, property)) {
		target = imager_remove_fits_property;
		snprintf(event, sizeof(event), "REMOVE %s", indigo_get_text_item_value(indigo_get_item(property, CCD_REMOVE_FITS_HEADER_KEYWORD_ITEM_NAME)));
	}
	if (target) {
		imager_record(event);
		indigo_property_copy_values(target, property, false);
		target->state = INDIGO_BUSY_STATE;
		indigo_update_property(device, target, NULL);
		target->state = target == imager_local_mode_property && atomic_load(&imager_checks_folder) && !indigo_uni_is_creatable(indigo_get_text_item_value(indigo_get_item(target, CCD_LOCAL_MODE_DIR_ITEM_NAME))) ? INDIGO_ALERT_STATE : INDIGO_OK_STATE;
		indigo_update_property(device, target, NULL);
	}
	return INDIGO_OK;
}

static indigo_device imager_standin = INDIGO_DEVICE_INITIALIZER("Imager Agent", NULL, imager_enumerate, imager_change, NULL, NULL);

static indigo_result aux_enumerate(indigo_device *device, indigo_client *client, indigo_property *property) {
	if (atomic_load(&safety_published) && indigo_property_match(safety_property, property)) {
		indigo_define_property(device, safety_property, NULL);
	}
	return INDIGO_OK;
}

static indigo_device aux_standin = INDIGO_DEVICE_INITIALIZER(AUX_AGENT_NAME, NULL, aux_enumerate, NULL, NULL, NULL);

// attaches the Auxiliary Agent stand-in with AGENT_AUX_SAFETY.SAFE in the given state
static bool aux_attach(indigo_property_state state) {
	safety_property->items[0].light.value = state;
	atomic_store(&safety_published, true);
	CHECK(indigo_attach_device(&aux_standin) == INDIGO_OK);
	aux_attached = true;
	indigo_define_property(&aux_standin, safety_property, NULL);
	// the scheduler evaluates the safety every 0.5 s
	indigo_usleep(700000);
	return true;
}

static void set_safety(indigo_property_state state) {
	safety_property->items[0].light.value = state;
	indigo_update_property(&aux_standin, safety_property, NULL);
}

// an ALERT that reverts to OK at once, faster than the scheduler evaluates the safety
static void safety_blip(void) {
	set_safety(INDIGO_ALERT_STATE);
	set_safety(INDIGO_OK_STATE);
}

// deletes AGENT_AUX_SAFETY while the stand-in stays attached
static void delete_safety(void) {
	atomic_store(&safety_published, false);
	indigo_delete_property(&aux_standin, safety_property, NULL);
}

static bool set_safety_hooks(const char *unsafe, const char *safe) {
	unsigned before = revision(AGENT_SCHEDULER_HOOKS_PROPERTY_NAME);
	const char *items[] = { AGENT_SCHEDULER_HOOKS_UNSAFE_ITEM_NAME, AGENT_SCHEDULER_HOOKS_SAFE_ITEM_NAME };
	const char *values[] = { unsafe, safe };
	indigo_change_text_property(&observer, AGENT, AGENT_SCHEDULER_HOOKS_PROPERTY_NAME, 2, items, values);
	return wait_property_state(AGENT_SCHEDULER_HOOKS_PROPERTY_NAME, before, INDIGO_OK_STATE, NULL);
}

// how a missing safety counts: as safe (the default) or as unsafe
static bool set_missing(bool unsafe) {
	unsigned before = revision(AGENT_SCHEDULER_SAFETY_MISSING_PROPERTY_NAME);
	indigo_change_switch_property_1(&observer, AGENT, AGENT_SCHEDULER_SAFETY_MISSING_PROPERTY_NAME, unsafe ? AGENT_SCHEDULER_SAFETY_MISSING_UNSAFE_ITEM_NAME : AGENT_SCHEDULER_SAFETY_MISSING_SAFE_ITEM_NAME, true);
	return wait_property_state(AGENT_SCHEDULER_SAFETY_MISSING_PROPERTY_NAME, before, INDIGO_OK_STATE, NULL);
}

// position of the event, a whole line of the log, at or after the offset; -1 if there is none
static long imager_position(const char *event, long after) {
	char line[1100];
	snprintf(line, sizeof(line), "\n%s\n", event);
	pthread_mutex_lock(&imager_mutex);
	// the last line has no newline yet when it is the end of the log
	char *log = indigo_safe_malloc(strlen(imager_log) + 2);
	sprintf(log, "%s\n", imager_log);
	pthread_mutex_unlock(&imager_mutex);
	const char *found = strstr(log + (after > 0 ? after : 0), line);
	long result = found ? (long)(found - log) : -1;
	free(log);
	return result;
}

// waits for the event after the offset and returns its position, -1 after the timeout
static long wait_imager_event(const char *event, long after, double timeout) {
	for (double t = 0; t < timeout; t += 0.01) {
		long position = imager_position(event, after);
		if (position >= 0) {
			return position;
		}
		indigo_usleep(10000);
	}
	pthread_mutex_lock(&imager_mutex);
	fprintf(stderr, "Timeout waiting for the Imager Agent event '%s' after %ld, log:%s\n", event, after, imager_log);
	pthread_mutex_unlock(&imager_mutex);
	return -1;
}

// the offset at which the next event of the log starts
static long imager_log_end(void) {
	pthread_mutex_lock(&imager_mutex);
	long end = (long)strlen(imager_log);
	pthread_mutex_unlock(&imager_mutex);
	return end;
}

static int imager_events(const char *prefix) {
	char line[1100];
	snprintf(line, sizeof(line), "\n%s", prefix);
	pthread_mutex_lock(&imager_mutex);
	int count = 0;
	for (const char *s = imager_log; (s = strstr(s, line)) != NULL; s += strlen(line)) {
		count++;
	}
	pthread_mutex_unlock(&imager_mutex);
	return count;
}

// the session night of the FITS keyword SCHNIGHT: the local date, the day before until noon
static void night_event(char *event, time_t t) {
	struct tm local;
	t -= 12 * 3600;
	localtime_r(&t, &local);
	sprintf(event, "SET SCHNIGHT='%04d-%02d-%02d'", local.tm_year + 1900, local.tm_mon + 1, local.tm_mday);
}

static bool set_data(bool object, bool fits, bool folder) {
	unsigned before = revision(AGENT_SCHEDULER_DATA_PROPERTY_NAME);
	const char *items[] = { AGENT_SCHEDULER_DATA_OBJECT_ITEM_NAME, AGENT_SCHEDULER_DATA_FITS_ITEM_NAME, AGENT_SCHEDULER_DATA_FOLDER_ITEM_NAME };
	bool values[] = { object, fits, folder };
	indigo_change_switch_property(&observer, AGENT, AGENT_SCHEDULER_DATA_PROPERTY_NAME, 3, items, values);
	return wait_property_state(AGENT_SCHEDULER_DATA_PROPERTY_NAME, before, INDIGO_OK_STATE, NULL);
}

static bool set_data_base(const char *base) {
	return change_text(AGENT_SCHEDULER_DATA_DIR_PROPERTY_NAME, AGENT_SCHEDULER_DATA_DIR_BASE_ITEM_NAME, base, INDIGO_OK_STATE, NULL);
}

// the plan labels and states, the count or -1 when the property is missing; a redefine at a minute boundary deletes it for a moment
static int plan_items(char labels[][INDIGO_VALUE_SIZE], indigo_property_state *states, int max) {
	indigo_property *property = snapshot(AGENT_SCHEDULER_PLAN_PROPERTY_NAME);
	for (int i = 0; i < 100 && property == NULL; i++) {
		indigo_usleep(10000);
		property = snapshot(AGENT_SCHEDULER_PLAN_PROPERTY_NAME);
	}
	if (property == NULL) {
		return -1;
	}
	int count = property->count;
	for (int i = 0; i < count && i < max; i++) {
		strcpy(labels[i], property->items[i].label);
		states[i] = property->items[i].light.value;
	}
	indigo_release_property(property);
	return count;
}

// waits until the plan has count items and the item at index contains text
static bool wait_plan_item(int count, int index, const char *text, double timeout) {
	char labels[16][INDIGO_VALUE_SIZE];
	indigo_property_state states[16];
	int found = -1;
	for (double t = 0; t < timeout; t += 0.01) {
		found = plan_items(labels, states, 16);
		if (found == count && (count == 0 || strstr(labels[index], text))) {
			return true;
		}
		indigo_usleep(10000);
	}
	fprintf(stderr, "Timeout waiting for a plan of %d items with '%s' at %d, found %d:\n", count, text, index, found);
	for (int i = 0; i < found && i < 16; i++) {
		fprintf(stderr, "  %s [%d]\n", labels[i], states[i]);
	}
	return false;
}

// waits until some plan item contains text, or with present false until none does
static bool wait_plan_contains(const char *text, bool present, double timeout) {
	char labels[32][INDIGO_VALUE_SIZE];
	indigo_property_state states[32];
	int found = -1;
	for (double t = 0; t < timeout; t += 0.01) {
		found = plan_items(labels, states, 32);
		bool contains = false;
		for (int i = 0; i < found && i < 32; i++) {
			contains = contains || strstr(labels[i], text) != NULL;
		}
		if (found >= 0 && contains == present) {
			return true;
		}
		indigo_usleep(10000);
	}
	fprintf(stderr, "Timeout waiting for a plan %s '%s', found %d:\n", present ? "with" : "without", text, found);
	for (int i = 0; i < found && i < 32; i++) {
		fprintf(stderr, "  %s [%d]\n", labels[i], states[i]);
	}
	return false;
}

static bool wait_plan(int count, const char *text, double timeout) {
	return wait_plan_item(count, 0, text, timeout);
}

// waits until the first planned run contains text and has the state, Busy for the running task
static bool wait_plan_first(const char *text, indigo_property_state state, double timeout) {
	char labels[16][INDIGO_VALUE_SIZE];
	indigo_property_state states[16];
	int found = -1;
	for (double t = 0; t < timeout; t += 0.01) {
		found = plan_items(labels, states, 16);
		if (found > 0 && states[0] == state && strstr(labels[0], text)) {
			return true;
		}
		indigo_usleep(10000);
	}
	fprintf(stderr, "Timeout waiting for '%s' in state %d first in the plan, found %d:\n", text, state, found);
	for (int i = 0; i < found && i < 16; i++) {
		fprintf(stderr, "  %s [%d]\n", labels[i], states[i]);
	}
	return false;
}

// start and end of a planned run in minutes of the day, the label begins with "YYYY-MM-DD HH:MM-HH:MM"
static bool plan_times(const char *label, int *start, int *end) {
	int year, month, day, start_hour, start_minute, end_hour, end_minute;
	if (sscanf(label, "%d-%d-%d %d:%d-%d:%d", &year, &month, &day, &start_hour, &start_minute, &end_hour, &end_minute) != 7) {
		return false;
	}
	*start = start_hour * 60 + start_minute;
	*end = end_hour * 60 + end_minute;
	return true;
}

// splits a label into exactly 6 columns on " | ", the last column takes the rest; returns false if a column is missing or empty
static bool split_label(const char *label, char columns[6][INDIGO_VALUE_SIZE]) {
	const char *rest = label;
	for (int i = 0; i < 6; i++) {
		const char *end = i < 5 ? strstr(rest, " | ") : NULL;
		size_t length = end ? (size_t)(end - rest) : strlen(rest);
		if ((i < 5 && end == NULL) || length == 0) {
			return false;
		}
		memcpy(columns[i], rest, length);
		columns[i][length] = 0;
		rest += length + (end ? 3 : 0);
	}
	return true;
}

// every label of a light property has 6 non-empty columns and no byte above 0x7f (the tested names and reasons are ASCII); the count of items is returned or -1
static int check_columns(const char *property_name) {
	indigo_property *property = snapshot(property_name);
	if (property == NULL) {
		return -1;
	}
	int result = property->count;
	for (int i = 0; i < property->count; i++) {
		char columns[6][INDIGO_VALUE_SIZE];
		if (!split_label(property->items[i].label, columns)) {
			fprintf(stderr, "label '%s' of %s has no 6 columns\n", property->items[i].label, property_name);
			result = -1;
			break;
		}
		for (const unsigned char *c = (const unsigned char *)property->items[i].label; *c; c++) {
			if (*c >= 0x80) {
				fprintf(stderr, "label '%s' of %s is not ASCII\n", property->items[i].label, property_name);
				result = -1;
				break;
			}
		}
	}
	indigo_release_property(property);
	return result;
}

static int minutes_between(int from, int to) {
	return (to - from + 1440) % 1440;
}

// moves the site to the longitude where the mean solar time is 18:00, the next sunrise is then hours away whenever the case runs
static void site_at_evening(void) {
	time_t now = time(NULL);
	double hours = (now % 86400) / 3600.0;
	site_property->items[1].number.value = site_property->items[1].number.target = fmod((18 - hours) * 15 + 720, 360);
	indigo_update_property(&mount_standin, site_property, NULL);
}

// the night cases use the equator, where every night lasts about 11 hours at the nautical limit
#define NIGHT_LATITUDE		0
#define NIGHT_ELEVATION		140

static void set_site(double latitude, double longitude) {
	site_property->items[0].number.value = site_property->items[0].number.target = latitude;
	site_property->items[1].number.value = site_property->items[1].number.target = longitude;
	indigo_update_property(&mount_standin, site_property, NULL);
}

// the longitude where a nautical night starts (or ends) at target; the events move by 240 s per degree
static double night_longitude(time_t target, bool end) {
	static scheduler_nights nights;
	double longitude = 17.11;
	for (int i = 0; i < 6; i++) {
		indigo_scheduler_nights_build(&nights, target, NIGHT_LATITUDE, longitude, NIGHT_ELEVATION, -12, 0, 0);
		const scheduler_night *best = NULL;
		long best_error = 0;
		for (int j = 0; j < nights.count; j++) {
			const scheduler_night *night = nights.nights + j;
			if (end ? !night->end_known : !night->start_known) {
				continue;
			}
			long error = (long)((end ? night->end : night->start) - target);
			if (best == NULL || labs(error) < labs(best_error)) {
				best = night;
				best_error = error;
			}
		}
		if (best == NULL) {
			break;
		}
		longitude = fmod(longitude + best_error / 240.0 + 720, 360);
	}
	return longitude;
}

// a whole minute at least seconds ahead, so that a window can open with the night
static time_t minute_ahead(int seconds) {
	time_t t = time(NULL) + seconds;
	return t - t % 60 + 60;
}

static void wait_until(time_t t) {
	while (time(NULL) < t) {
		indigo_usleep(100000);
	}
}

static void set_guiding(bool guiding) {
	guider_process_property->items[0].sw.value = guiding;
	guider_process_property->state = guiding ? INDIGO_BUSY_STATE : INDIGO_OK_STATE;
	indigo_update_property(&guider_standin, guider_process_property, NULL);
}

// -------------------------------------------------------------------------------- Lifecycle

static bool start_scheduler(void) {
	CHECK(indigo_agent_scheduler(INDIGO_DRIVER_INIT, NULL) == INDIGO_OK);
	scheduler_running = true;
	for (int i = 0; i < 500 && revision(AGENT_SCHEDULER_SETTINGS_PROPERTY_NAME) == 0; i++) {
		indigo_usleep(10000);
	}
	CHECK(revision(AGENT_SCHEDULER_SETTINGS_PROPERTY_NAME) > 0);
	// let the configuration restore finish before the case changes anything
	indigo_usleep(300000);
	return fast_settings();
}

static void stop_scheduler(void) {
	if (scheduler_running) {
		indigo_agent_scheduler(INDIGO_DRIVER_SHUTDOWN, NULL);
		scheduler_running = false;
	}
}

static bool setup(void) {
	indigo_set_log_level(getenv("INDIGO_TEST_DEBUG") ? INDIGO_LOG_DEBUG : INDIGO_LOG_ERROR);
	CHECK(indigo_start() == INDIGO_OK);
	strcpy(observer.name, "Scheduler test observer");
	observer.version = INDIGO_VERSION_CURRENT;
	observer.define_property = observe;
	observer.update_property = observe;
	observer.delete_property = deleted;
	observer.send_message = message_received;
	CHECK(indigo_attach_client(&observer) == INDIGO_OK);
	site_property = indigo_init_number_property(NULL, mount_standin.name, GEOGRAPHIC_COORDINATES_PROPERTY_NAME, "Site", "Location", INDIGO_OK_STATE, INDIGO_RO_PERM, 3);
	indigo_init_number_item(site_property->items + 0, GEOGRAPHIC_COORDINATES_LATITUDE_ITEM_NAME, "Latitude", -90, 90, 0, 48.15);
	indigo_init_number_item(site_property->items + 1, GEOGRAPHIC_COORDINATES_LONGITUDE_ITEM_NAME, "Longitude", 0, 360, 0, 17.11);
	indigo_init_number_item(site_property->items + 2, GEOGRAPHIC_COORDINATES_ELEVATION_ITEM_NAME, "Elevation", -400, 9000, 0, 140);
	guider_process_property = indigo_init_switch_property(NULL, guider_standin.name, AGENT_START_PROCESS_PROPERTY_NAME, "Guider", "Start process", INDIGO_OK_STATE, INDIGO_RW_PERM, INDIGO_AT_MOST_ONE_RULE, 1);
	indigo_init_switch_item(guider_process_property->items, "GUIDING", "Guiding", false);
	guider_abort_property = indigo_init_switch_property(NULL, guider_standin.name, AGENT_ABORT_PROCESS_PROPERTY_NAME, "Guider", "Abort", INDIGO_OK_STATE, INDIGO_RW_PERM, INDIGO_AT_MOST_ONE_RULE, 1);
	indigo_init_switch_item(guider_abort_property->items, AGENT_ABORT_PROCESS_ITEM_NAME, "Abort", false);
	CHECK(indigo_attach_device(&mount_standin) == INDIGO_OK);
	mount_attached = true;
	CHECK(indigo_attach_device(&guider_standin) == INDIGO_OK);
	guider_attached = true;
	imager_local_mode_property = indigo_init_text_property(NULL, imager_standin.name, CCD_LOCAL_MODE_PROPERTY_NAME, "Imager", "Local mode", INDIGO_OK_STATE, INDIGO_RW_PERM, 3);
	indigo_init_text_item(imager_local_mode_property->items + 0, CCD_LOCAL_MODE_DIR_ITEM_NAME, "Directory", IMAGER_DIR);
	indigo_init_text_item(imager_local_mode_property->items + 1, CCD_LOCAL_MODE_PREFIX_ITEM_NAME, "Prefix", "IMG_");
	indigo_init_text_item(imager_local_mode_property->items + 2, CCD_LOCAL_MODE_OBJECT_ITEM_NAME, "Object", IMAGER_OBJECT);
	imager_set_fits_property = indigo_init_text_property(NULL, imager_standin.name, CCD_SET_FITS_HEADER_PROPERTY_NAME, "Imager", "Set FITS header", INDIGO_OK_STATE, INDIGO_RW_PERM, 2);
	indigo_init_text_item(imager_set_fits_property->items + 0, CCD_SET_FITS_HEADER_KEYWORD_ITEM_NAME, "Keyword", "");
	indigo_init_text_item(imager_set_fits_property->items + 1, CCD_SET_FITS_HEADER_VALUE_ITEM_NAME, "Value", "");
	imager_remove_fits_property = indigo_init_text_property(NULL, imager_standin.name, CCD_REMOVE_FITS_HEADERS_PROPERTY_NAME, "Imager", "Remove FITS header", INDIGO_OK_STATE, INDIGO_RW_PERM, 1);
	indigo_init_text_item(imager_remove_fits_property->items + 0, CCD_REMOVE_FITS_HEADER_KEYWORD_ITEM_NAME, "Keyword", "");
	imager_ccd_list_property = indigo_init_switch_property(NULL, imager_standin.name, FILTER_CCD_LIST_PROPERTY_NAME, "Imager", "Camera", INDIGO_OK_STATE, INDIGO_RW_PERM, INDIGO_ONE_OF_MANY_RULE, 2);
	indigo_init_switch_item(imager_ccd_list_property->items + 0, FILTER_DEVICE_LIST_NONE_ITEM_NAME, "No camera", false);
	indigo_init_switch_item(imager_ccd_list_property->items + 1, "CCD Imager Simulator", "CCD Imager Simulator", true);
	CHECK(indigo_attach_device(&imager_standin) == INDIGO_OK);
	imager_attached = true;
	// created here, attached only by the cases of the unsafe hold
	safety_property = indigo_init_light_property(NULL, aux_standin.name, AGENT_AUX_SAFETY_PROPERTY_NAME, "Safety", "Safety", INDIGO_OK_STATE, 1);
	indigo_init_light_item(safety_property->items + 0, AGENT_AUX_SAFETY_SAFE_ITEM_NAME, "Safe", INDIGO_OK_STATE);
	CHECK(indigo_agent_scripting(INDIGO_DRIVER_INIT, NULL) == INDIGO_OK);
	scripting_running = true;
	return start_scheduler();
}

static void cleanup(void) {
	stop_scheduler();
	if (scripting_running) {
		indigo_agent_scripting(INDIGO_DRIVER_SHUTDOWN, NULL);
	}
	if (imager_attached) {
		indigo_detach_device(&imager_standin);
		imager_attached = false;
	}
	if (aux_attached) {
		indigo_detach_device(&aux_standin);
		aux_attached = false;
	}
	if (guider_attached) {
		indigo_detach_device(&guider_standin);
	}
	if (mount_attached) {
		indigo_detach_device(&mount_standin);
	}
	indigo_detach_client(&observer);
	indigo_stop();
	for (unsigned i = 0; i < ARRAY_SIZE(cache); i++) {
		indigo_release_property(cache[i].property);
	}
	indigo_release_property(site_property);
	indigo_release_property(guider_process_property);
	indigo_release_property(guider_abort_property);
	indigo_release_property(imager_local_mode_property);
	indigo_release_property(imager_set_fits_property);
	indigo_release_property(imager_remove_fits_property);
	indigo_release_property(imager_ccd_list_property);
	indigo_release_property(safety_property);
}

// -------------------------------------------------------------------------------- Cases

static bool upload_placed(const char *name, double hour_angle, double declination, const char *header);

static void store_edit_and_delete(void) {
	REQUIRE(upload("// @task Alpha\n// @priority high 70\n\n" BODY_WAIT(1)));
	indigo_property *task = snapshot("AGENT_SCHEDULER_TASK_0");
	REQUIRE(task != NULL);
	ASSERT_STREQ("Alpha", task->label);
	ASSERT_TRUE(strstr(indigo_get_text_item_value(task->items), "// @priority high 70") != NULL);
	indigo_release_property(task);
	char label[INDIGO_VALUE_SIZE];
	ASSERT_TRUE(task_label("Alpha", label, NULL));
	ASSERT_TRUE(strstr(label, "QUEUED") != NULL);
	// invalid and duplicate uploads are rejected with the line and the problem
	char message[INDIGO_VALUE_SIZE];
	ASSERT_TRUE(change_text(AGENT_SCHEDULER_ADD_TASK_PROPERTY_NAME, AGENT_SCHEDULER_ADD_TASK_TASK_ITEM_NAME, "// @task Beta\n// @altitude > 30\n" BODY_WAIT(1), INDIGO_ALERT_STATE, message));
	ASSERT_TRUE(strstr(message, "require @target") != NULL);
	ASSERT_TRUE(change_text(AGENT_SCHEDULER_ADD_TASK_PROPERTY_NAME, AGENT_SCHEDULER_ADD_TASK_TASK_ITEM_NAME, "// @task Beta\n// @duration 0\n" BODY_WAIT(1), INDIGO_ALERT_STATE, message));
	ASSERT_TRUE(strstr(message, "line 2: @duration") != NULL);
	ASSERT_TRUE(change_text(AGENT_SCHEDULER_ADD_TASK_PROPERTY_NAME, AGENT_SCHEDULER_ADD_TASK_TASK_ITEM_NAME, "// @task alpha\n" BODY_WAIT(1), INDIGO_ALERT_STATE, message));
	ASSERT_TRUE(strstr(message, "already exists") != NULL);
	// an edit can rename the task, an invalid edit leaves it unchanged
	ASSERT_TRUE(change_text("AGENT_SCHEDULER_TASK_0", AGENT_SCHEDULER_TASK_TASK_ITEM_NAME, "// @task Gamma\n// @enabled maybe\n" BODY_WAIT(1), INDIGO_ALERT_STATE, message));
	ASSERT_TRUE(strstr(message, "@enabled") != NULL);
	ASSERT_TRUE(change_text("AGENT_SCHEDULER_TASK_0", AGENT_SCHEDULER_TASK_TASK_ITEM_NAME, "// @task Gamma\n" BODY_WAIT(2), INDIGO_OK_STATE, NULL));
	task = snapshot("AGENT_SCHEDULER_TASK_0");
	REQUIRE(task != NULL);
	ASSERT_STREQ("Gamma", task->label);
	ASSERT_TRUE(strstr(indigo_get_text_item_value(task->items), "wait(2)") != NULL);
	indigo_release_property(task);
	ASSERT_TRUE(task_label("Gamma", label, NULL));
	ASSERT_FALSE(task_label("Alpha", label, NULL));
	ASSERT_TRUE(change_text(AGENT_SCHEDULER_DELETE_TASK_PROPERTY_NAME, AGENT_SCHEDULER_DELETE_TASK_NAME_ITEM_NAME, "Gamma", INDIGO_OK_STATE, NULL));
	ASSERT_TRUE(snapshot("AGENT_SCHEDULER_TASK_0") == NULL);
	ASSERT_FALSE(task_label("Gamma", label, NULL));
	ASSERT_TRUE(change_text(AGENT_SCHEDULER_DELETE_TASK_PROPERTY_NAME, AGENT_SCHEDULER_DELETE_TASK_NAME_ITEM_NAME, "Gamma", INDIGO_ALERT_STATE, message));
	ASSERT_TRUE(strstr(message, "not found") != NULL);
}

static void commands_and_order(void) {
	REQUIRE(upload("// @task One\n" BODY_WAIT(1)));
	REQUIRE(upload("// @task Two\n" BODY_WAIT(1)));
	REQUIRE(upload("// @task Three\n" BODY_WAIT(1)));
	REQUIRE(command("Three", AGENT_SCHEDULER_TASK_COMMAND_MOVE_UP_ITEM_NAME));
	REQUIRE(command("One", AGENT_SCHEDULER_TASK_COMMAND_MOVE_DOWN_ITEM_NAME));
	indigo_property *list = snapshot(AGENT_SCHEDULER_TASK_STATE_PROPERTY_NAME);
	REQUIRE(list != NULL && list->count == 3);
	ASSERT_TRUE(!strncmp(list->items[0].label, "Three ", 6));
	ASSERT_TRUE(!strncmp(list->items[1].label, "One ", 4));
	ASSERT_TRUE(!strncmp(list->items[2].label, "Two ", 4));
	indigo_release_property(list);
	REQUIRE(command("Two", AGENT_SCHEDULER_TASK_COMMAND_DISABLE_ITEM_NAME));
	ASSERT_TRUE(wait_task_state("Two", "DISABLED", 2));
	REQUIRE(command("Two", AGENT_SCHEDULER_TASK_COMMAND_ENABLE_ITEM_NAME));
	ASSERT_TRUE(wait_task_state("Two", "QUEUED", 2));
	unsigned before = revision(AGENT_SCHEDULER_TASK_COMMAND_PROPERTY_NAME);
	REQUIRE(change_text(AGENT_SCHEDULER_TASK_NAME_PROPERTY_NAME, AGENT_SCHEDULER_TASK_NAME_NAME_ITEM_NAME, "Nobody", INDIGO_OK_STATE, NULL));
	indigo_change_switch_property_1(&observer, AGENT, AGENT_SCHEDULER_TASK_COMMAND_PROPERTY_NAME, AGENT_SCHEDULER_TASK_COMMAND_RESET_ITEM_NAME, true);
	ASSERT_TRUE(wait_property_state(AGENT_SCHEDULER_TASK_COMMAND_PROPERTY_NAME, before, INDIGO_ALERT_STATE, NULL));
}

static void run_order_by_priority(void) {
	REQUIRE(upload("// @task Low\n// @priority low 90\n" BODY_WAIT(1)));
	REQUIRE(upload("// @task Normal\n// @priority normal 10\n" BODY_WAIT(1)));
	REQUIRE(upload("// @task High\n// @priority high 0\n" BODY_WAIT(1)));
	REQUIRE(control(AGENT_SCHEDULER_CONTROL_START_ITEM_NAME));
	ASSERT_TRUE(wait_message("Starting task 'High'", 1, 15));
	// a task uploaded while another one runs never interrupts it
	REQUIRE(upload("// @task Later\n// @priority high 100\n" BODY_WAIT(1)));
	ASSERT_TRUE(wait_message("All tasks finished", 1, 30));
	long high = message_position("Task 'High' completed");
	long later = message_position("Starting task 'Later'");
	long normal = message_position("Starting task 'Normal'");
	long low = message_position("Starting task 'Low'");
	ASSERT_TRUE(high >= 0 && later > high && normal > later && low > normal);
	ASSERT_TRUE(wait_task_state("Low", "DONE", 2));
	ASSERT_TRUE(wait_scheduler_state(INDIGO_OK_STATE, 2));
	indigo_property *state = snapshot(AGENT_SCHEDULER_STATE_PROPERTY_NAME);
	REQUIRE(state != NULL);
	ASSERT_EQ_INT(4, (int)indigo_get_item(state, AGENT_SCHEDULER_STATE_DONE_ITEM_NAME)->number.value);
	ASSERT_EQ_INT(4, (int)indigo_get_item(state, AGENT_SCHEDULER_STATE_TOTAL_ITEM_NAME)->number.value);
	indigo_release_property(state);
}

static void window_wait_and_expiry(void) {
	time_t now = time(NULL);
	char start[32], end[32], short_end[32];
	// the window opens at the next whole minute, at least 10 s ahead so the case sees it closed first
	time_t open = now - now % 60 + 60;
	if (open - now < 10) {
		open += 60;
	}
	utc(open, start);
	utc(open + 3600, end);
	utc(open, short_end);
	char text[512];
	snprintf(text, sizeof(text), "// @task Window\n// @window %s .. %s\n// @duration 1\n" BODY_WAIT(1), start, end);
	REQUIRE(upload(text));
	// a task whose window closes before its duration elapses never starts and expires
	snprintf(text, sizeof(text), "// @task TooShort\n// @window .. %s\n// @duration 5\n" BODY_WAIT(1), short_end);
	REQUIRE(upload(text));
	REQUIRE(control(AGENT_SCHEDULER_CONTROL_START_ITEM_NAME));
	ASSERT_TRUE(wait_task_state("Window", "WAITING", 5));
	ASSERT_TRUE(wait_reason("window", 5));
	indigo_property *current = snapshot(AGENT_SCHEDULER_CURRENT_PROPERTY_NAME);
	REQUIRE(current != NULL);
	ASSERT_EQ_INT(2, current->count);
	ASSERT_STREQ(AGENT_SCHEDULER_CURRENT_CURRENT_ITEM_NAME, current->items[0].name);
	ASSERT_STREQ(AGENT_SCHEDULER_CURRENT_REASON_ITEM_NAME, current->items[1].name);
	indigo_release_property(current);
	ASSERT_EQ_INT(0, count_messages("Starting task 'Window'"));
	ASSERT_TRUE(wait_message("Starting task 'Window'", 1, (double)(open - time(NULL)) + 5));
	ASSERT_TRUE(time(NULL) >= open);
	ASSERT_TRUE(wait_task_state("Window", "DONE", 10));
	ASSERT_TRUE(wait_task_state("TooShort", "EXPIRED", 5));
	ASSERT_EQ_INT(0, count_messages("Starting task 'TooShort'"));
}

static void target_below_horizon_waits(void) {
	// a target that never rises can never run and is UNREACHABLE (see plan_lists_the_night), this one is 30 degrees below the horizon and rises in four hours
	set_site(0, 17.11);
	REQUIRE(upload_placed("South", 8, 0, "// @duration 1\n"));
	REQUIRE(control(AGENT_SCHEDULER_CONTROL_START_ITEM_NAME));
	ASSERT_TRUE(wait_task_state("South", "WAITING", 5));
	ASSERT_TRUE(wait_reason("target below the horizon", 5));
	ASSERT_EQ_INT(0, count_messages("Starting task 'South'"));
}

static void repeat_retry_and_failures(void) {
	REQUIRE(upload("// @task Twice\n// @repeat 2\n" BODY_WAIT(1)));
	// fails only when it runs, its estimate passes
	REQUIRE(upload("// @task Broken\n// @priority low\n// @retry 1\nif (!scheduler_task.estimate) { throw new Error(\"broken body\"); }\n" BODY_WAIT(1)));
	// a body that cannot run at all is found by its estimate and never runs
	REQUIRE(upload("// @task Syntax\n// @priority low 10\nvar = ;\n"));
	REQUIRE(upload("// @task Thrown\n// @priority low 20\nthrow new Error(\"always\");\n"));
	REQUIRE(upload("// @task NoStart\n// @priority low 0\nvar sequence = new Sequence(scheduler_task.name);\nsequence.wait(1);\n"));
	REQUIRE(control(AGENT_SCHEDULER_CONTROL_START_ITEM_NAME));
	ASSERT_TRUE(wait_message("Task 'Twice' completed run 1 of 2", 1, 15));
	ASSERT_TRUE(wait_message("Task 'Twice' completed", 2, 15));
	ASSERT_TRUE(wait_task_state("Twice", "DONE", 5));
	ASSERT_TRUE(wait_message("Task 'Broken' failed: Error: broken body, it will be retried", 1, 15));
	ASSERT_TRUE(wait_task_state("Broken", "FAILED", 15));
	ASSERT_EQ_INT(2, count_messages("Starting task 'Broken'"));
	ASSERT_TRUE(wait_task_state("Syntax", "SCRIPT ERROR", 15));
	ASSERT_TRUE(wait_message("Task 'Syntax' has a script error: SyntaxError", 1, 5));
	ASSERT_TRUE(wait_task_state("Thrown", "SCRIPT ERROR", 15));
	ASSERT_TRUE(wait_message("Task 'Thrown' has a script error: Error: always", 1, 5));
	ASSERT_EQ_INT(0, count_messages("Starting task 'Syntax'"));
	ASSERT_EQ_INT(0, count_messages("Starting task 'Thrown'"));
	ASSERT_TRUE(wait_task_state("NoStart", "FAILED", 15));
	ASSERT_TRUE(wait_message("Task 'NoStart' failed: the sequence was not started", 1, 5));
	ASSERT_TRUE(wait_message("All tasks finished", 1, 10));
}

static void quoted_name_reaches_the_body(void) {
	REQUIRE(upload("// @task Q \"a\" \\ b\nif (scheduler_task.name != \"Q \\\"a\\\" \\\\ b\") { throw new Error(\"wrong name \" + scheduler_task.name); }\n" BODY_WAIT(1)));
	REQUIRE(control(AGENT_SCHEDULER_CONTROL_START_ITEM_NAME));
	ASSERT_TRUE(wait_task_state("Q \"a\" \\ b", "DONE", 15));
}

static void urgent_preempts_and_task_is_retried(void) {
	REQUIRE(upload("// @task Long\n// @retry 1\n" BODY_WAIT(30)));
	REQUIRE(control(AGENT_SCHEDULER_CONTROL_START_ITEM_NAME));
	ASSERT_TRUE(wait_task_state("Long", "RUNNING", 15));
	set_guiding(true);
	indigo_usleep(1500000);
	REQUIRE(urgent("// @task Flash\n// @priority low\n" BODY_WAIT(1)));
	ASSERT_TRUE(wait_message("Task 'Long' preempted by an urgent task, it will be retried", 1, 10));
	ASSERT_TRUE(atomic_load(&guider_aborts) >= 1);
	ASSERT_TRUE(wait_message("Starting task 'Flash'", 1, 10));
	long preempted = message_position("Task 'Long' preempted");
	long flash = message_position("Starting task 'Flash'");
	ASSERT_TRUE(flash > preempted);
	ASSERT_TRUE(wait_message("Task 'Flash' completed", 1, 10));
	// the unstored urgent task is gone, the preempted one runs again from the beginning without using a retry
	char label[INDIGO_VALUE_SIZE];
	ASSERT_TRUE(wait_message("Starting task 'Long'", 2, 10));
	ASSERT_FALSE(task_label("Flash", label, NULL));
	ASSERT_TRUE(task_label("Long", label, NULL));
	ASSERT_TRUE(strstr(label, "retries left 1") != NULL);
	REQUIRE(control(AGENT_SCHEDULER_CONTROL_ABORT_ITEM_NAME));
	ASSERT_TRUE(wait_task_state("Long", "RETRY", 10));
}

static void preempted_task_fails_when_asked(void) {
	REQUIRE(upload("// @task Fragile\n// @preempted fail\n" BODY_WAIT(30)));
	REQUIRE(control(AGENT_SCHEDULER_CONTROL_START_ITEM_NAME));
	ASSERT_TRUE(wait_task_state("Fragile", "RUNNING", 15));
	indigo_usleep(1000000);
	REQUIRE(urgent("// @task Burst\n" BODY_WAIT(1)));
	ASSERT_TRUE(wait_task_state("Fragile", "FAILED", 10));
	ASSERT_TRUE(wait_message("Task 'Burst' completed", 1, 10));
	ASSERT_EQ_INT(1, count_messages("Starting task 'Fragile'"));
}

