	REQUIRE(upload(text));
	REQUIRE(set_night_hooks("Evening", "Morning", ""));
	REQUIRE(command("Evening", AGENT_SCHEDULER_TASK_COMMAND_DISABLE_ITEM_NAME));
	set_site(NIGHT_LATITUDE, night_longitude(dusk, false));
