static void data_settings_persist(void) {
	REQUIRE(set_data(false, false, true));
	REQUIRE(set_data_base("/archive"));
	stop_scheduler();
	REQUIRE(start_scheduler());
	indigo_property *data = snapshot(AGENT_SCHEDULER_DATA_PROPERTY_NAME);
	REQUIRE(data != NULL);
	ASSERT_FALSE(indigo_get_item(data, AGENT_SCHEDULER_DATA_OBJECT_ITEM_NAME)->sw.value);
	ASSERT_FALSE(indigo_get_item(data, AGENT_SCHEDULER_DATA_FITS_ITEM_NAME)->sw.value);
	ASSERT_TRUE(indigo_get_item(data, AGENT_SCHEDULER_DATA_FOLDER_ITEM_NAME)->sw.value);
	indigo_release_property(data);
	indigo_property *base = snapshot(AGENT_SCHEDULER_DATA_DIR_PROPERTY_NAME);
	REQUIRE(base != NULL);
	ASSERT_STREQ("/archive", indigo_get_text_item_value(indigo_get_item(base, AGENT_SCHEDULER_DATA_DIR_BASE_ITEM_NAME)));
	indigo_release_property(base);
}

static void data_defaults(void) {
	indigo_property *data = snapshot(AGENT_SCHEDULER_DATA_PROPERTY_NAME);
	REQUIRE(data != NULL);
	ASSERT_EQ_INT(INDIGO_ANY_OF_MANY_RULE, data->rule);
	ASSERT_TRUE(indigo_get_item(data, AGENT_SCHEDULER_DATA_OBJECT_ITEM_NAME)->sw.value);
	ASSERT_TRUE(indigo_get_item(data, AGENT_SCHEDULER_DATA_FITS_ITEM_NAME)->sw.value);
	ASSERT_FALSE(indigo_get_item(data, AGENT_SCHEDULER_DATA_FOLDER_ITEM_NAME)->sw.value);
	indigo_release_property(data);
	indigo_property *base = snapshot(AGENT_SCHEDULER_DATA_DIR_PROPERTY_NAME);
	REQUIRE(base != NULL);
	ASSERT_STREQ("", indigo_get_text_item_value(indigo_get_item(base, AGENT_SCHEDULER_DATA_DIR_BASE_ITEM_NAME)));
	indigo_release_property(base);
}

// MERIDIAN_FLIP of the Scripting Agent as the observer sees it: ENABLED, or -1 while it is not defined
static int observed_flip(double *offset) {
	pthread_mutex_lock(&cache_mutex);
	observation *entry = find(SCRIPTING_AGENT_NAME, "MERIDIAN_FLIP");
	int result = -1;
	if (entry && entry->property) {
		indigo_item *enabled = indigo_get_item(entry->property, "ENABLED");
		indigo_item *item = indigo_get_item(entry->property, "OFFSET");
		if (enabled && item) {
			result = enabled->number.value > 0.5;
			*offset = item->number.value;
		}
	}
	pthread_mutex_unlock(&cache_mutex);
	return result;
}

static bool wait_flip(int enabled, double offset, double timeout) {
	double observed = 0;
	for (double t = 0; t < timeout; t += 0.01) {
		if (observed_flip(&observed) == enabled && (enabled < 0 || fabs(observed - offset) < 1e-9)) {
			return true;
		}
		indigo_usleep(10000);
	}
	fprintf(stderr, "Timeout waiting for MERIDIAN_FLIP %d %g, observed %d %g\n", enabled, offset, observed_flip(&observed), observed);
	return false;
}

static void run_script(const char *script) {
	const char *items[] = { AGENT_SCRIPTING_RUN_SCRIPT_ITEM_NAME };
	const char *values[] = { script };
	indigo_change_text_property(&observer, SCRIPTING_AGENT_NAME, AGENT_SCRIPTING_RUN_SCRIPT_PROPERTY_NAME, 1, items, values);
}

// publishes the meridian flip as set_meridian_flip() of Sequencer.js does, through its global, which a reload of the library keeps
static bool set_flip(bool enabled, double offset) {
	char script[512];
	snprintf(script, sizeof(script), "indigo_meridian_flip.enabled = %s; indigo_meridian_flip.offset = %g; indigo_update_number_property(\"%s\", \"MERIDIAN_FLIP\", indigo_meridian_flip_items(), \"Ok\");", enabled ? "true" : "false", offset, SCRIPTING_AGENT_NAME);
	run_script(script);
	return wait_flip(enabled, offset, 5);
}

// a 60 minute run of a target 90 minutes before the meridian at the equator: VISIBILITY centres it on the meridian, 30 minutes ahead, unless the flip penalty moves it past
static bool start_with_crossing_task(void) {
	CHECK(set_setting(AGENT_SCHEDULER_SETTINGS_VISIBILITY_FLIP_PENALTY_ITEM_NAME, 0));
	CHECK(set_strategy(AGENT_SCHEDULER_STRATEGY_VISIBILITY_ITEM_NAME));
	set_site(0, longitude_at_hour(20));
	CHECK(upload_placed("Crossing", -1.5, 0, "// @duration 60\n"));
	CHECK(control(AGENT_SCHEDULER_CONTROL_START_ITEM_NAME));
	// Sequencer.js defines MERIDIAN_FLIP disabled when it is loaded
	CHECK(wait_flip(0, 0, 15));
	CHECK(wait_task_state("Crossing", "QUEUED", 10));
	CHECK(wait_plan_contains("Crossing", true, 10));
	CHECK(wait_plan_contains("meridian flip", false, 5));
	return true;
}

static void visibility_flip_change_replans(void) {
	REQUIRE(start_with_crossing_task());
	ASSERT_TRUE(set_flip(true, 0));
	ASSERT_TRUE(wait_plan_contains("| Crossing | run 1/1 | normal 50 | PLANNED | meridian flip", true, 10));
	// the penalty moves the run past the meridian
	ASSERT_TRUE(set_setting(AGENT_SCHEDULER_SETTINGS_VISIBILITY_FLIP_PENALTY_ITEM_NAME, 10));
	ASSERT_TRUE(wait_plan_contains("meridian flip", false, 10));
	ASSERT_TRUE(wait_plan_contains("| Crossing | run 1/1 | normal 50 | PLANNED | -", true, 5));
	// back without the penalty, then an offset the run does not reach
	ASSERT_TRUE(set_setting(AGENT_SCHEDULER_SETTINGS_VISIBILITY_FLIP_PENALTY_ITEM_NAME, 0));
	ASSERT_TRUE(wait_plan_contains("meridian flip", true, 10));
	ASSERT_TRUE(set_flip(true, 1));
	ASSERT_TRUE(wait_plan_contains("meridian flip", false, 10));
	ASSERT_EQ_INT(0, count_messages("Starting task 'Crossing'"));
}

static void visibility_flip_unchanged_update_keeps_the_plan(void) {
	REQUIRE(start_with_crossing_task());
	ASSERT_TRUE(set_flip(true, 0));
	ASSERT_TRUE(wait_plan_contains("meridian flip", true, 10));
	char before[32][INDIGO_VALUE_SIZE], after[32][INDIGO_VALUE_SIZE];
	indigo_property_state states[32];
	int count = plan_items(before, states, 32);
	REQUIRE(count > 0);
	unsigned flip_revision = 0;
	pthread_mutex_lock(&cache_mutex);
	observation *entry = find(SCRIPTING_AGENT_NAME, "MERIDIAN_FLIP");
	flip_revision = entry ? entry->revision : 0;
	pthread_mutex_unlock(&cache_mutex);
	ASSERT_TRUE(set_flip(true, 0));
	// the same update arrived and the plan labels stay
	for (int i = 0; i < 500; i++) {
		pthread_mutex_lock(&cache_mutex);
		unsigned now = entry ? entry->revision : 0;
		pthread_mutex_unlock(&cache_mutex);
		if (now != flip_revision) {
			break;
		}
		indigo_usleep(10000);
	}
	indigo_usleep(2000000);
	ASSERT_EQ_INT(count, plan_items(after, states, 32));
	for (int i = 0; i < count; i++) {
		ASSERT_STREQ(before[i], after[i]);
	}
}

static void visibility_flip_delete_disables(void) {
	REQUIRE(start_with_crossing_task());
	ASSERT_TRUE(set_flip(true, 0));
	ASSERT_TRUE(wait_plan_contains("meridian flip", true, 10));
	run_script("indigo_delete_property(\"" SCRIPTING_AGENT_NAME "\", \"MERIDIAN_FLIP\");");
	ASSERT_TRUE(wait_flip(-1, 0, 5));
	ASSERT_TRUE(wait_plan_contains("meridian flip", false, 10));
	// defined again with the values the library kept
	run_script("indigo_sequencer.on_enumerate_properties({ device: \"" SCRIPTING_AGENT_NAME "\", name: \"MERIDIAN_FLIP\" });");
	ASSERT_TRUE(wait_flip(1, 0, 5));
	ASSERT_TRUE(wait_plan_contains("meridian flip", true, 10));
}

// the flip is marked under COMPACT too, as information
static void compact_marks_the_flip(void) {
	set_site(0, longitude_at_hour(20));
	// a window that opens in 20 minutes, when the target is about 16 minutes before the meridian
	char start[32], header[128];
	utc(minute_ahead(1200), start);
	snprintf(header, sizeof(header), "// @duration 60\n// @window %s ..\n", start);
	REQUIRE(upload_placed("Crossing", -0.6, 0, header));
	REQUIRE(control(AGENT_SCHEDULER_CONTROL_START_ITEM_NAME));
	ASSERT_TRUE(wait_flip(0, 0, 15));
	ASSERT_TRUE(wait_plan_contains("| Crossing | run 1/1 | normal 50 | PLANNED | -", true, 10));
	ASSERT_TRUE(set_flip(true, 0));
	ASSERT_TRUE(wait_plan_contains("| Crossing | run 1/1 | normal 50 | PLANNED | meridian flip", true, 10));
	ASSERT_EQ_INT(0, count_messages("Starting task 'Crossing'"));
}

// -------------------------------------------------------------------------------- Unsafe hold

#define THROWING_BODY(message) "if (!scheduler_task.estimate) { throw new Error(\"" message "\"); }\n" BODY_WAIT(1)

// the scheduler night started an hour ago
static void site_in_night(void) {
	set_site(NIGHT_LATITUDE, night_longitude(time(NULL) - 3600, false));
}

// waits until the oldest history entry of the task, given as for history_label(), contains text
static bool history_has(const char *task, const char *text) {
	char label[INDIGO_VALUE_SIZE];
	for (int i = 0; i < 300; i++) {
		if (history_label(task, 0, label) && strstr(label, text)) {
			return true;
		}
		indigo_usleep(10000);
	}
	fprintf(stderr, "No history entry of '%s' with '%s'\n", task, text);
	return false;
}

// starts the scheduler with Work running; Work and the hooks are uploaded by the case
static bool start_with_work_running(void) {
	CHECK(control(AGENT_SCHEDULER_CONTROL_START_ITEM_NAME));
	CHECK(wait_task_state("Work", "RUNNING", 15));
	indigo_usleep(1000000);
	return true;
}

static void unsafe_hold_aborts_a_running_task(void) {
	REQUIRE(set_setting(AGENT_SCHEDULER_SETTINGS_SAFE_DELAY_ITEM_NAME, 0));
	REQUIRE(upload("// @task Secure\n" BODY_WAIT(1)));
	REQUIRE(upload("// @task Work\n// @retry 1\n// @preempted retry\n" BODY_WAIT(30)));
	REQUIRE(set_safety_hooks("Secure", ""));
	REQUIRE(aux_attach(INDIGO_OK_STATE));
	REQUIRE(start_with_work_running());
	set_guiding(true);
	set_safety(INDIGO_ALERT_STATE);
	ASSERT_TRUE(wait_message("Unsafe conditions, the scheduler holds", 1, 5));
	ASSERT_TRUE(wait_message("Task 'Work' aborted by unsafe conditions, it will be retried", 1, 10));
	ASSERT_TRUE(atomic_load(&guider_aborts) >= 1);
	ASSERT_TRUE(wait_message("Hook 'Secure' completed", 1, 15));
	ASSERT_TRUE(message_position("Task 'Work' aborted") < message_position("Starting hook 'Secure'"));
	ASSERT_TRUE(wait_reason("unsafe conditions", 5));
	ASSERT_TRUE(history_has("Work #1", "| task | UNSAFE | unsafe conditions"));
	// the run used no retry and had no retry delay
	ASSERT_TRUE(wait_task_state("Work", "QUEUED", 5));
	char label[INDIGO_VALUE_SIZE];
	ASSERT_TRUE(task_label("Work", label, NULL) && strstr(label, "retries left 1"));
	indigo_property *state = snapshot(AGENT_SCHEDULER_STATE_PROPERTY_NAME);
	REQUIRE(state != NULL);
	ASSERT_EQ_INT(INDIGO_BUSY_STATE, state->state);
	indigo_release_property(state);
	indigo_usleep(2000000);
	ASSERT_EQ_INT(1, count_messages("Starting task 'Work'"));
	ASSERT_EQ_INT(1, count_messages("Starting hook 'Secure'"));
	set_safety(INDIGO_OK_STATE);
	ASSERT_TRUE(wait_message("Safe conditions, the unsafe hold ends", 1, 10));
	ASSERT_TRUE(wait_message("Starting task 'Work'", 2, 10));
	ASSERT_EQ_INT(1, count_messages("Starting hook 'Secure'"));
	REQUIRE(control(AGENT_SCHEDULER_CONTROL_ABORT_ITEM_NAME));
}

static void unsafe_hold_fails_a_task_with_preempted_fail(void) {
	REQUIRE(set_setting(AGENT_SCHEDULER_SETTINGS_SAFE_DELAY_ITEM_NAME, 0));
	REQUIRE(upload("// @task Secure\n" BODY_WAIT(1)));
	REQUIRE(upload("// @task Work\n// @retry 1\n// @preempted fail\n" BODY_WAIT(30)));
	REQUIRE(set_safety_hooks("Secure", ""));
	REQUIRE(aux_attach(INDIGO_OK_STATE));
	REQUIRE(start_with_work_running());
	set_safety(INDIGO_ALERT_STATE);
	ASSERT_TRUE(wait_message("Task 'Work' aborted by unsafe conditions and failed", 1, 10));
	ASSERT_EQ_INT(0, count_messages("Task 'Work' aborted by unsafe conditions, it will be retried"));
	ASSERT_TRUE(history_has("Work #1", "| task | UNSAFE | unsafe conditions"));
	// @preempted fail applies as after an urgent preemption, the retry is not used
	ASSERT_TRUE(wait_task_state("Work", "FAILED", 5));
	ASSERT_TRUE(wait_message("Hook 'Secure' completed", 1, 15));
	set_safety(INDIGO_OK_STATE);
	ASSERT_TRUE(wait_message("Safe conditions, the unsafe hold ends", 1, 10));
	indigo_usleep(2000000);
	ASSERT_EQ_INT(1, count_messages("Starting task 'Work'"));
	ASSERT_TRUE(wait_task_state("Work", "FAILED", 1));
	REQUIRE(control(AGENT_SCHEDULER_CONTROL_ABORT_ITEM_NAME));
}

static void unsafe_hold_aborts_an_urgent_task(void) {
	REQUIRE(set_setting(AGENT_SCHEDULER_SETTINGS_SAFE_DELAY_ITEM_NAME, 0));
	REQUIRE(aux_attach(INDIGO_OK_STATE));
	REQUIRE(control(AGENT_SCHEDULER_CONTROL_START_ITEM_NAME));
	REQUIRE(urgent("// @task Flash\n" BODY_WAIT(8)));
	ASSERT_TRUE(wait_task_state("Flash", "RUNNING", 15));
	indigo_usleep(1000000);
	set_safety(INDIGO_ALERT_STATE);
	ASSERT_TRUE(wait_message("Task 'Flash' aborted by unsafe conditions, it will be retried", 1, 10));
	ASSERT_TRUE(history_has("Flash #1", "| urgent | UNSAFE | unsafe conditions"));
	// the one-off urgent task stays in the list
	ASSERT_TRUE(wait_task_state("Flash", "QUEUED", 5));
	indigo_usleep(2000000);
	ASSERT_EQ_INT(1, count_messages("Starting task 'Flash'"));
	set_safety(INDIGO_OK_STATE);
	ASSERT_TRUE(wait_message("Starting task 'Flash'", 2, 10));
	ASSERT_TRUE(wait_message("Task 'Flash' completed", 1, 20));
	ASSERT_TRUE(wait_task_removed("Flash", 5));
}

static void unsafe_hold_fails_an_urgent_task_with_preempted_fail(void) {
	REQUIRE(set_setting(AGENT_SCHEDULER_SETTINGS_SAFE_DELAY_ITEM_NAME, 0));
	REQUIRE(aux_attach(INDIGO_OK_STATE));
	REQUIRE(control(AGENT_SCHEDULER_CONTROL_START_ITEM_NAME));
	REQUIRE(urgent("// @task Flash\n// @preempted fail\n" BODY_WAIT(8)));
	ASSERT_TRUE(wait_task_state("Flash", "RUNNING", 15));
	indigo_usleep(1000000);
	set_safety(INDIGO_ALERT_STATE);
	ASSERT_TRUE(wait_message("Task 'Flash' aborted by unsafe conditions and failed", 1, 10));
	ASSERT_TRUE(history_has("Flash #1", "| urgent | UNSAFE | unsafe conditions"));
	// the ended one-off urgent task leaves the list and is counted as an urgent failure
	ASSERT_TRUE(wait_task_removed("Flash", 5));
	ASSERT_TRUE(wait_counter(AGENT_SCHEDULER_STATE_URGENT_FAILED_ITEM_NAME, 1, 5));
	ASSERT_EQ_INT(0, state_counter(AGENT_SCHEDULER_STATE_URGENT_DONE_ITEM_NAME));
	set_safety(INDIGO_OK_STATE);
	ASSERT_TRUE(wait_message("Safe conditions, the unsafe hold ends", 1, 10));
	indigo_usleep(2000000);
	ASSERT_EQ_INT(1, count_messages("Starting task 'Flash'"));
}

static void unsafe_hold_aborts_a_hand_started_sequence(void) {
	REQUIRE(set_setting(AGENT_SCHEDULER_SETTINGS_SAFE_DELAY_ITEM_NAME, 0));
	REQUIRE(upload("// @task Secure\n" BODY_WAIT(1)));
	REQUIRE(set_safety_hooks("Secure", ""));
	REQUIRE(aux_attach(INDIGO_OK_STATE));
	REQUIRE(control(AGENT_SCHEDULER_CONTROL_START_ITEM_NAME));
	ASSERT_TRUE(wait_sequence_state(INDIGO_OK_STATE, 15) || wait_sequence_state(INDIGO_IDLE_STATE, 1));
	const char *items[] = { AGENT_SCRIPTING_RUN_SCRIPT_ITEM_NAME };
	const char *first[] = { "var manual = new Sequence(\"Manual\");\nmanual.wait(30);\nmanual.start();\n" };
	indigo_change_text_property(&observer, SCRIPTING_AGENT_NAME, AGENT_SCRIPTING_RUN_SCRIPT_PROPERTY_NAME, 1, items, first);
	ASSERT_TRUE(wait_sequence_state(INDIGO_BUSY_STATE, 5));
	ASSERT_TRUE(wait_reason("another sequence is running", 5));
	set_safety(INDIGO_ALERT_STATE);
	ASSERT_TRUE(wait_message("A sequence started by hand was aborted by unsafe conditions", 1, 10));
	ASSERT_TRUE(wait_message("Hook 'Secure' completed", 1, 15));
	ASSERT_TRUE(message_position("A sequence started by hand was aborted") < message_position("Starting hook 'Secure'"));
	// a sequence started by hand during the hold is left alone
	const char *second[] = { "var manual = new Sequence(\"Manual\");\nmanual.wait(3);\nmanual.start();\n" };
	indigo_change_text_property(&observer, SCRIPTING_AGENT_NAME, AGENT_SCRIPTING_RUN_SCRIPT_PROPERTY_NAME, 1, items, second);
	ASSERT_TRUE(wait_sequence_state(INDIGO_BUSY_STATE, 5));
	ASSERT_TRUE(wait_reason("another sequence is running", 5));
	ASSERT_TRUE(wait_sequence_state(INDIGO_OK_STATE, 10));
	ASSERT_EQ_INT(1, count_messages("A sequence started by hand was aborted"));
	ASSERT_EQ_INT(1, count_messages("Starting hook 'Secure'"));
	set_safety(INDIGO_OK_STATE);
	ASSERT_TRUE(wait_message("Safe conditions, the unsafe hold ends", 1, 10));
}

static void unsafe_hold_lets_shutdown_finish(void) {
	char future[32], text[256];
	utc(time(NULL) + 2 * 86400, future);
	REQUIRE(set_setting(AGENT_SCHEDULER_SETTINGS_SAFE_DELAY_ITEM_NAME, 0));
	REQUIRE(upload("// @task Close\n" BODY_WAIT(4)));
	REQUIRE(upload("// @task Secure\n" BODY_WAIT(1)));
	REQUIRE(upload("// @task Work\n" BODY_WAIT(1)));
	snprintf(text, sizeof(text), "// @task Later\n// @window %s ..\n" BODY_WAIT(1), future);
	REQUIRE(upload(text));
	REQUIRE(set_hooks("", "Close", ""));
	REQUIRE(set_safety_hooks("Secure", ""));
	REQUIRE(aux_attach(INDIGO_OK_STATE));
	REQUIRE(control(AGENT_SCHEDULER_CONTROL_START_ITEM_NAME));
	ASSERT_TRUE(wait_message("Task 'Work' completed", 1, 15));
	REQUIRE(control(AGENT_SCHEDULER_CONTROL_STOP_ITEM_NAME));
	ASSERT_TRUE(wait_message("Starting hook 'Close'", 1, 15));
	indigo_usleep(1000000);
	set_safety(INDIGO_ALERT_STATE);
	ASSERT_TRUE(wait_message("Unsafe conditions, the scheduler holds", 1, 5));
	ASSERT_TRUE(wait_message("Hook 'Close' completed", 1, 15));
	ASSERT_TRUE(wait_scheduler_state(INDIGO_OK_STATE, 5));
	ASSERT_TRUE(history_has("Close", "| hook | SUCCEEDED | -"));
	indigo_usleep(1500000);
	// the stop runs the shutdown hook, the unsafe hook does not run
	ASSERT_EQ_INT(0, count_messages("aborted by unsafe conditions"));
	ASSERT_EQ_INT(0, count_messages("Starting hook 'Secure'"));
}

static void unsafe_hold_lets_night_end_finish(void) {
	REQUIRE(set_setting(AGENT_SCHEDULER_SETTINGS_SAFE_DELAY_ITEM_NAME, 0));
	REQUIRE(upload("// @task Morning\n" BODY_WAIT(4)));
	REQUIRE(upload("// @task Secure\n" BODY_WAIT(1)));
	REQUIRE(set_safety_hooks("Secure", ""));
	REQUIRE(aux_attach(INDIGO_OK_STATE));
	REQUIRE(start_in_night("Morning", ""));
	set_site(NIGHT_LATITUDE, night_longitude(time(NULL) + 3, true));
	ASSERT_TRUE(wait_message("Starting hook 'Morning'", 1, 30));
	indigo_usleep(1000000);
	set_safety(INDIGO_ALERT_STATE);
	ASSERT_TRUE(wait_message("Hook 'Morning' completed", 1, 15));
	ASSERT_TRUE(wait_message("Hook 'Secure' completed", 1, 15));
	ASSERT_TRUE(message_position("Hook 'Morning' completed") < message_position("Starting hook 'Secure'"));
	ASSERT_TRUE(history_has("Morning", "| hook | SUCCEEDED | -"));
	ASSERT_EQ_INT(0, count_messages("aborted by unsafe conditions"));
}

static void unsafe_hold_aborts_the_startup_hook(void) {
	REQUIRE(set_setting(AGENT_SCHEDULER_SETTINGS_SAFE_DELAY_ITEM_NAME, 0));
	REQUIRE(upload("// @task Prepare\n" BODY_WAIT(6)));
	REQUIRE(upload("// @task Secure\n" BODY_WAIT(1)));
	REQUIRE(upload("// @task Work\n" BODY_WAIT(1)));
	REQUIRE(set_hooks("Prepare", "", ""));
	REQUIRE(set_safety_hooks("Secure", ""));
	REQUIRE(aux_attach(INDIGO_OK_STATE));
	REQUIRE(control(AGENT_SCHEDULER_CONTROL_START_ITEM_NAME));
	ASSERT_TRUE(wait_message("Starting hook 'Prepare'", 1, 15));
	indigo_usleep(1000000);
	set_safety(INDIGO_ALERT_STATE);
	ASSERT_TRUE(wait_message("Hook 'Prepare' aborted by unsafe conditions", 1, 10));
	ASSERT_TRUE(history_has("Prepare", "| hook | UNSAFE | unsafe conditions"));
	// the startup hook may have prepared half of the equipment, the unsafe hook runs
	ASSERT_TRUE(wait_message("Hook 'Secure' completed", 1, 15));
	ASSERT_TRUE(wait_scheduler_state(INDIGO_BUSY_STATE, 1));
	ASSERT_EQ_INT(0, count_messages("The startup hook failed"));
	set_safety(INDIGO_OK_STATE);
	ASSERT_TRUE(wait_message("Safe conditions, the scheduler starts", 1, 10));
	ASSERT_TRUE(wait_message("Starting hook 'Prepare'", 2, 10));
	ASSERT_TRUE(wait_message("Task 'Work' completed", 1, 20));
	ASSERT_TRUE(message_position_last("Hook 'Prepare' completed") < message_position("Starting task 'Work'"));
}

